// @FIGURE_CODE_BEGIN
// coordinate axes with arrowheads → black Line + ConeGeometry arrowheads along math x, math y, z axes
// dashed hidden guides → LineDashedMaterial segments from origin along base-plane axes and up z-axis
// tick at x=2 → short black Line across the positive x-axis
// paraboloid cap z=4-x^2-y^2 → dynamic colored BufferGeometry mesh over z>=0, blue-to-orange vertex colors
// outer rim z=0 → LineSegments from marching squares of cap(x,y)=0
// cylinder wall (x-1)^2+y^2=1 → dynamic translucent blue vertical strip mesh from base to cap
// base disk → dynamic translucent filled grid patch in xy-plane where c(x,y)<=0
// intersection/top curve → LineSegments along c(x,y)=0 lifted to z=cap(x,y)
// bounded top patch → colored mesh over c(x,y)<=0 below the cap
// movable horizontal slicing plane → translucent yellow horizontal PlaneGeometry at z=h
// filled cross-section → yellow grid patch where c(x,y)<=0 and cap(x,y)>=h
// highlight overlays → duplicate translucent meshes/bright line overlays controlled by selector
// leader arrows → black line plus cone from equation labels to cap and base boundary

const mathToWorld = (x, y, z) => new THREE.Vector3(x, z, y);

const root = new THREE.Group();
scene.add(root);

const staticGroup = new THREE.Group();
const dynamicGroup = new THREE.Group();
root.add(staticGroup, dynamicGroup);

let capFn = (x, y) => 4 - x * x - y * y;
let boundFn = (x, y) => (x - 1) * (x - 1) + y * y - 1;
let currentH = 1;

const matAxis = new THREE.LineBasicMaterial({ color: 0x111111 });
const matDash = new THREE.LineDashedMaterial({ color: 0x777777, dashSize: 0.10, gapSize: 0.07, transparent: true, opacity: 0.55 });
const blue = new THREE.Color(0x4f9ed4);
const lightBlue = new THREE.Color(0x7eb6df);
const orange = new THREE.Color(0xe9543f);
const cream = new THREE.Color(0xf6ead0);

function disposeObject(obj) {
  obj.traverse(o => {
    if (o.geometry) o.geometry.dispose();
    if (Array.isArray(o.material)) o.material.forEach(m => m.dispose());
    else if (o.material) o.material.dispose();
  });
}

function clearGroup(g) {
  while (g.children.length) {
    const ch = g.children.pop();
    disposeObject(ch);
  }
}

function addLine(points, material, parent = staticGroup) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const line = new THREE.Line(geom, material);
  if (material.isLineDashedMaterial) line.computeLineDistances();
  parent.add(line);
  return line;
}

function addSegments(points, material, parent = dynamicGroup) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const line = new THREE.LineSegments(geom, material);
  if (material.isLineDashedMaterial) line.computeLineDistances();
  parent.add(line);
  return line;
}

function addArrow(start, end, color = 0x111111, parent = staticGroup, headLen = 0.16, headRad = 0.045) {
  const dir = new THREE.Vector3().subVectors(end, start);
  const len = dir.length();
  if (len <= 1e-6) return new THREE.Group();
  const group = new THREE.Group();
  const shaftEnd = start.clone().add(dir.clone().setLength(Math.max(0.01, len - headLen)));
  addLine([start, shaftEnd], new THREE.LineBasicMaterial({ color }), group);
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(headRad, headLen, 24),
    new THREE.MeshBasicMaterial({ color })
  );
  cone.position.copy(shaftEnd.clone().add(dir.clone().setLength(headLen / 2)));
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  group.add(cone);
  parent.add(group);
  return group;
}

function colorForHeight(z) {
  const t = THREE.MathUtils.clamp(z / 4, 0, 1);
  const c = new THREE.Color();
  if (t < 0.55) c.lerpColors(blue, lightBlue, t / 0.55);
  else c.lerpColors(lightBlue, orange, (t - 0.55) / 0.45);
  return c;
}

function safeEval(fn, x, y) {
  try {
    const v = fn(x, y);
    return Number.isFinite(v) ? v : NaN;
  } catch {
    return NaN;
  }
}

function buildGridSurface({ domain = [-2.2, 2.2], n = 72, predicate, heightFn, opacity = 0.62, side = THREE.DoubleSide }) {
  const [a, b] = domain;
  const step = (b - a) / n;
  const verts = [];
  const colors = [];
  const indices = [];
  const idx = new Map();
  function key(i, j) { return i + "," + j; }
  function addVertex(i, j) {
    const k = key(i, j);
    if (idx.has(k)) return idx.get(k);
    const x = a + i * step;
    const y = a + j * step;
    const z = heightFn(x, y);
    const id = verts.length / 3;
    const p = mathToWorld(x, y, z);
    verts.push(p.x, p.y, p.z);
    const col = colorForHeight(z);
    colors.push(col.r, col.g, col.b);
    idx.set(k, id);
    return id;
  }
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const cx = a + (i + 0.5) * step;
      const cy = a + (j + 0.5) * step;
      if (!predicate(cx, cy)) continue;
      const zc = heightFn(cx, cy);
      if (!Number.isFinite(zc)) continue;
      const i00 = addVertex(i, j), i10 = addVertex(i + 1, j), i11 = addVertex(i + 1, j + 1), i01 = addVertex(i, j + 1);
      indices.push(i00, i10, i11, i00, i11, i01);
    }
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute("position", new THREE.Float32BufferAttribute(verts, 3));
  geom.setAttribute("color", new THREE.Float32BufferAttribute(colors, 3));
  geom.setIndex(indices);
  geom.computeVertexNormals();
  geom.computeBoundingSphere();
  const mat = new THREE.MeshBasicMaterial({
    vertexColors: true,
    side,
    transparent: true,
    opacity,
    depthWrite: false
  });
  return new THREE.Mesh(geom, mat);
}

function buildFlatRegion({ h = 0, domain = [-2.2, 2.2], n = 78, predicate, color = 0x9dcced, opacity = 0.48 }) {
  const [a, b] = domain;
  const step = (b - a) / n;
  const verts = [];
  const indices = [];
  const idx = new Map();
  function key(i, j) { return i + "," + j; }
  function addVertex(i, j) {
    const k = key(i, j);
    if (idx.has(k)) return idx.get(k);
    const x = a + i * step;
    const y = a + j * step;
    const id = verts.length / 3;
    const p = mathToWorld(x, y, h);
    verts.push(p.x, p.y, p.z);
    idx.set(k, id);
    return id;
  }
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const cx = a + (i + 0.5) * step;
      const cy = a + (j + 0.5) * step;
      if (!predicate(cx, cy)) continue;
      const i00 = addVertex(i, j), i10 = addVertex(i + 1, j), i11 = addVertex(i + 1, j + 1), i01 = addVertex(i, j + 1);
      indices.push(i00, i10, i11, i00, i11, i01);
    }
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute("position", new THREE.Float32BufferAttribute(verts, 3));
  geom.setIndex(indices);
  geom.computeVertexNormals();
  geom.computeBoundingSphere();
  return new THREE.Mesh(geom, new THREE.MeshBasicMaterial({
    color,
    transparent: true,
    opacity,
    side: THREE.DoubleSide,
    depthWrite: false
  }));
}

function marchingSegments(valueFn, domain = [-2.2, 2.2], n = 96, level = 0) {
  const [a, b] = domain;
  const step = (b - a) / n;
  const segs = [];
  const interp = (p, q, vp, vq) => {
    const t = Math.abs(vq - vp) < 1e-9 ? 0.5 : (level - vp) / (vq - vp);
    return [p[0] + THREE.MathUtils.clamp(t, 0, 1) * (q[0] - p[0]), p[1] + THREE.MathUtils.clamp(t, 0, 1) * (q[1] - p[1])];
  };
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const x0 = a + i * step, x1 = x0 + step;
      const y0 = a + j * step, y1 = y0 + step;
      const p = [[x0, y0], [x1, y0], [x1, y1], [x0, y1]];
      const v = p.map(q => safeEval(valueFn, q[0], q[1]));
      if (v.some(q => !Number.isFinite(q))) continue;
      const crossings = [];
      for (const [u, w] of [[0, 1], [1, 2], [2, 3], [3, 0]]) {
        const du = v[u] - level, dw = v[w] - level;
