// @FIGURE_CODE_BEGIN
// coordinate axes with arrowheads → black Line + ConeGeometry arrowheads for math x, math y, z axes
// dashed hidden guides → gray dashed Line segments from origin along positive base-plane axes and up z-axis
// tick at x=2 → short black Line crossing the positive x-axis
// paraboloid cap z=4-x^2-y^2 → polar/grid BufferGeometry mesh, transparent blue-to-orange vertex colors
// outer rim x^2+y^2=4 at z=0 → dark blue LineLoop/LineSegments
// cylinder wall (x-1)^2+y^2=1 → transparent vertical strip mesh clipped by cap
// base disk → transparent blue filled grid patch in xy-plane where c(x,y)<=0
// projected base boundary → dark blue boundary LineSegments at z=0
// cylinder/paraboloid intersection curve → red-brown LineSegments lifted to z=cap(x,y)
// cream hollow cylinder upper rim/interior → narrow cream mesh band just inside the clipped cylinder top
// horizontal slice plane and filled cross-section → hidden by default; translucent pale yellow mesh + outline when slider/demo requests it
// highlight overlays → hidden by default, shown after highlight interaction or demo step
// leader arrows → black line plus cone from equation callouts to paraboloid and cylinder/base boundary

const mathToWorld = (x, y, z) => new THREE.Vector3(y, z, x);

const root = new THREE.Group();
scene.add(root);

const staticGroup = new THREE.Group();
const dynamicGroup = new THREE.Group();
root.add(staticGroup, dynamicGroup);

let capFn = (x, y) => 4 - x * x - y * y;
let boundFn = (x, y) => (x - 1) * (x - 1) + y * y - 1;
let currentH = 1;
let showSlice = false;
let highlightActive = false;

const matAxis = new THREE.LineBasicMaterial({ color: 0x111111 });
const matDash = new THREE.LineDashedMaterial({ color: 0x777777, dashSize: 0.11, gapSize: 0.075, transparent: true, opacity: 0.55 });
const blue = new THREE.Color(0x4f9ed4);
const lightBlue = new THREE.Color(0x7eb6df);
const orange = new THREE.Color(0xe9543f);
const cream = new THREE.Color(0xf6ead0);

function disposeObject(obj) {
  obj.traverse?.(o => {
    o.geometry?.dispose?.();
    if (Array.isArray(o.material)) o.material.forEach(m => m.dispose?.());
    else o.material?.dispose?.();
  });
}

function clearGroup(g) {
  while (g.children.length) {
    const ch = g.children.pop();
    disposeObject(ch);
  }
}

function addLine(points, material, parent = staticGroup) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const line = new THREE.Line(geom, material);
  if (material.isLineDashedMaterial) line.computeLineDistances();
  parent.add(line);
  return line;
}

function addSegments(points, material, parent = dynamicGroup) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const line = new THREE.LineSegments(geom, material);
  if (material.isLineDashedMaterial) line.computeLineDistances();
  parent.add(line);
  return line;
}

function addArrow(start, end, color = 0x111111, parent = staticGroup, headLen = 0.16, headRad = 0.043) {
  const dir = new THREE.Vector3().subVectors(end, start);
  const len = dir.length();
  if (len <= 1e-6) return new THREE.Group();
  const group = new THREE.Group();
  const shaftEnd = start.clone().add(dir.clone().setLength(Math.max(0.01, len - headLen)));
  addLine([start, shaftEnd], new THREE.LineBasicMaterial({ color }), group);
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(headRad, headLen, 24),
    new THREE.MeshBasicMaterial({ color })
  );
  cone.position.copy(shaftEnd.clone().add(dir.clone().setLength(headLen / 2)));
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  group.add(cone);
  parent.add(group);
  return group;
}

function colorForHeight(z) {
  const t = THREE.MathUtils.clamp(z / 4, 0, 1);
  const c = new THREE.Color();
  if (t < 0.58) c.lerpColors(blue, lightBlue, t / 0.58);
  else c.lerpColors(lightBlue, orange, (t - 0.58) / 0.42);
  return c;
}

function safeEval(fn, x, y) {
  try {
    const v = fn(x, y);
    return Number.isFinite(v) ? v : NaN;
  } catch {
    return NaN;
  }
}

function buildPolarCap({ radial = 44, angular = 160, opacity = 0.56 }) {
  const verts = [];
  const colors = [];
  const indices = [];
  for (let i = 0; i <= radial; i++) {
    const r = 2 * i / radial;
    for (let j = 0; j <= angular; j++) {
      const th = 2 * Math.PI * j / angular;
      const x = r * Math.cos(th);
      const y = r * Math.sin(th);
      const raw = safeEval(capFn, x, y);
      const z = Math.max(0, Number.isFinite(raw) ? raw : 0);
      const p = mathToWorld(x, y, z);
      verts.push(p.x, p.y, p.z);
      const col = colorForHeight(z);
      colors.push(col.r, col.g, col.b);
    }
  }
  const row = angular + 1;
  for (let i = 0; i < radial; i++) {
    for (let j = 0; j < angular; j++) {
      const a = i * row + j;
      const b = (i + 1) * row + j;
      const c = (i + 1) * row + j + 1;
      const d0 = i * row + j + 1;
      indices.push(a, b, c, a, c, d0);
    }
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute("position", new THREE.Float32BufferAttribute(verts, 3));
  geom.setAttribute("color", new THREE.Float32BufferAttribute(colors, 3));
  geom.setIndex(indices);
  geom.computeVertexNormals();
  geom.computeBoundingSphere();
  return new THREE.Mesh(geom, new THREE.MeshBasicMaterial({
    vertexColors: true,
    side: THREE.DoubleSide,
    transparent: true,
    opacity,
    depthWrite: false
  }));
}

function buildGridSurface({ domain = [-2.2, 2.2], n = 72, predicate, heightFn, opacity = 0.62, color = null }) {
  const [a, b] = domain;
  const step = (b - a) / n;
  const verts = [];
  const colors = [];
  const indices = [];
  const idx = new Map();
  function key(i, j) { return i + "," + j; }
  function addVertex(i, j) {
    const k = key(i, j);
    if (idx.has(k)) return idx.get(k);
    const x = a + i * step;
    const y = a + j * step;
    const z = heightFn(x, y);
    const id = verts.length / 3;
    const p = mathToWorld(x, y, z);
    verts.push(p.x, p.y, p.z);
    const col = color ? new THREE.Color(color) : colorForHeight(z);
    colors.push(col.r, col.g, col.b);
    idx.set(k, id);
    return id;
  }
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const cx = a + (i + 0.5) * step;
      const cy = a + (j + 0.5) * step;
      if (!predicate(cx, cy)) continue;
      const zc = heightFn(cx, cy);
      if (!Number.isFinite(zc)) continue;
      const i00 = addVertex(i, j), i10 = addVertex(i + 1, j), i11 = addVertex(i + 1, j + 1), i01 = addVertex(i, j + 1);
      indices.push(i00, i10, i11, i00, i11, i01);
    }
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute("position", new THREE.Float32BufferAttribute(verts, 3));
  geom.setAttribute("color", new THREE.Float32BufferAttribute(colors, 3));
  geom.setIndex(indices);
  geom.computeVertexNormals();
  geom.computeBoundingSphere();
  return new THREE.Mesh(geom, new THREE.MeshBasicMaterial({
    vertexColors: true,
    side: THREE.DoubleSide,
    transparent: true,
    opacity,
    depthWrite: false
  }));
}

function buildFlatRegion({ h = 0, domain = [-2.2, 2.2], n = 80, predicate, color = 0x78b5dd, opacity = 0.42 }) {
  const [a, b] = domain;
  const step = (b - a) / n;
  const verts = [];
  const indices = [];
  const idx = new Map();
  function key(i, j) { return i + "," + j; }
  function addVertex(i, j) {
    const k = key(i, j);
    if (idx.has(k)) return idx.get(k);
    const x = a + i * step;
    const y = a + j * step;
    const id = verts.length / 3;
    const p = mathToWorld(x, y, h);
    verts.push(p.x, p.y, p.z);
    idx.set(k, id);
    return id;
  }
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const cx = a + (i + 0.5) * step;
      const cy = a + (j + 0.5) * step;
      if (!predicate(cx, cy)) continue;
      const i00 = addVertex(i, j), i10 = addVertex(i + 1, j), i11 = addVertex(i + 1, j + 1), i01 = addVertex(i, j + 1);
      indices.push(i00, i10, i11, i00, i11, i01);
    }
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute("position", new THREE.Float32BufferAttribute(verts, 3));
  geom.setIndex(indices);
  geom.computeVertexNormals();
  geom.computeBoundingSphere();
  return new THREE.Mesh(geom, new THREE.MeshBasicMaterial({
    color,
    transparent: true,
    opacity,
    side: THREE.DoubleSide,
    depthWrite: false
  }));
}

function marchingSegments(valueFn, domain = [-2.2, 2.2], n = 112, level = 0) {
  const [a, b] = domain;
  const step = (b - a) / n;
  const segs = [];
  const interp = (p, q, vp, vq) => {
    const t = Math.abs(vq - vp) < 1e-9 ? 0.5 : (level - vp) / (vq - vp);
    const u = THREE.MathUtils.clamp(t, 0, 1);
    return [p[0] + u * (q[0] - p[0]), p[1] + u * (q[1] - p[1])];
  };
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const x0 = a + i * step, x1 = x0 + step;
      const y0 = a + j * step, y1 = y0 + step;
      const p = [[x0, y0], [x1, y0], [x1, y1], [x0, y1]];
      const v = p.map(q => safeEval(valueFn, q[0], q[1]));
      if (v.some(q => !Number.isFinite(q))) continue;
      const crossings = [];
      for (const [u, w] of [[0, 1], [1, 2], [2, 3], [3, 0]]) {
        const du = v[u] - level, dw = v[w] - level;
        if ((du <= 0 && dw > 0) || (du > 0 && dw <= 0)) crossings.push(interp(p[u], p[w], v[u], v[w]));
      }
      if (crossings.length === 2) segs.push([crossings[0], crossings[1]]);
      else if (crossings.length === 4) {
        segs.push([crossings[0], crossings[1]], [crossings[2], crossings[3]]);
      }
    }
  }
  return segs;
}

function linePointsFromSegs(segs, hFn) {
  const pts = [];
  for (const [a, b] of segs) {
    const za = hFn(a[0], a[1]);
    const zb = hFn(b[0], b[1]);
    if (!Number.isFinite(za) || !Number.isFinite(zb)) continue;
    pts.push(mathToWorld(a[0], a[1], za), mathToWorld(b[0], b[1], zb));
  }
  return pts;
}

function buildWallFromBoundary(segs) {
  const verts = [];
  const indices = [];
  let k = 0;
  for (const [a, b] of segs) {
    const za = Math.max(0, safeEval(capFn, a[0], a[1]));
    const zb = Math.max(0, safeEval(capFn, b[0], b[1]));
    if (!Number.isFinite(za) || !Number.isFinite(zb)) continue;
    const p0 = mathToWorld(a[0], a[1], 0);
    const p1 = mathToWorld(b[0], b[1], 0);
    const p2 = mathToWorld(b[0], b[1], zb);
    const p3 = mathToWorld(a[0], a[1], za);
    verts.push(p0.x, p0.y, p0.z, p1.x, p1.y, p1.z, p2.x, p2.y, p2.z, p3.x, p3.y, p3.z);
    indices.push(k, k + 1, k + 2, k, k + 2, k + 3);
    k += 4;
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute("position", new THREE.Float32BufferAttribute(verts, 3));
  geom.setIndex(indices);
  geom.computeVertexNormals();
  geom.computeBoundingSphere();
  return new THREE.Mesh(geom, new THREE.MeshBasicMaterial({
    color: 0x4f9ed4,
    transparent: true,
    opacity: 0.46,
    side: THREE.DoubleSide,
    depthWrite: false
  }));
}

function buildCreamRimBand() {
  const verts = [];
  const indices = [];
  const cols = 58;
  const rows = 3;
  for (let i = 0; i <= cols; i++) {
    const t = Math.PI * 0.15 + Math.PI * 1.35 * i / cols;
    for (let j = 0; j <= rows; j++) {
      const rho = 1 - 0.18 * j / rows;
      const x = 1 + rho * Math.cos(t);
      const y = rho * Math.sin(t);
      const z = Math.max(0, safeEval(capFn, 1 + Math.cos(t), Math.sin(t))) - 0.018 * j + 0.012;
      const p = mathToWorld(x, y, z);
      verts.push(p.x, p.y, p.z);
    }
  }
  const stride = rows + 1;
  for (let i = 0; i < cols; i++) {
    for (let j = 0; j < rows; j++) {
      const a = i * stride + j;
      const b = (i + 1) * stride + j;
      const c = (i + 1) * stride + j + 1;
      const d0 = i * stride + j + 1;
      indices.push(a, b, c, a, c, d0);
    }
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute("position", new THREE.Float32BufferAttribute(verts, 3));
  geom.setIndex(indices);
  geom.computeVertexNormals();
  geom.computeBoundingSphere();
  return new THREE.Mesh(geom, new THREE.MeshBasicMaterial({
    color: cream,
    transparent: true,
    opacity: 0.78,
    side: THREE.DoubleSide,
    depthWrite: false
  }));
}

function buildSlicePlane(h) {
  const geom = new THREE.PlaneGeometry(4.4, 4.4);
  geom.rotateX(-Math.PI / 2);
  const mesh = new THREE.Mesh(geom, new THREE.MeshBasicMaterial({
    color: 0xfff0a0,
    transparent: true,
    opacity: 0.08,
    side: THREE.DoubleSide,
    depthWrite: false
  }));
  mesh.position.y = h;
  return mesh;
}

const axisEndX = mathToWorld(2.85, 0, 0);
const axisEndY = mathToWorld(0, 2.85, 0);
const axisEndZ = mathToWorld(0, 0, 4.65);

addArrow(mathToWorld(-0.65, 0, 0), axisEndX, 0x111111, staticGroup, 0.17, 0.042);
addArrow(mathToWorld(0, -2.35, 0), axisEndY, 0x111111, staticGroup, 0.17, 0.042);
addArrow(mathToWorld(0, 0, 0), axisEndZ, 0x111111, staticGroup, 0.17, 0.042);
addLine([mathToWorld(0, 0, 0), mathToWorld(2.25, 0, 0)], matDash, staticGroup);
addLine([mathToWorld(0, 0, 0), mathToWorld(0, 2.35, 0)], matDash, staticGroup);
addLine([mathToWorld(0, 0, 0), mathToWorld(0, 0, 4.25)], matDash, staticGroup);
addLine([mathToWorld(2, -0.085, 0), mathToWorld(2, 0.085, 0)], matAxis, staticGroup);

const labelCapPos = mathToWorld(2.20, 1.78, 3.48);
const labelBasePos = mathToWorld(1.52, -1.30, -0.62);
addArrow(labelCapPos, mathToWorld(0.70, 0.45, 3.15), 0x111111, staticGroup, 0.12, 0.035);
addArrow(labelBasePos, mathToWorld(1.65, -0.18, 0.08), 0x111111, staticGroup, 0.12, 0.035);

let fullCapMesh, topPatchMesh, wallMesh, baseMesh, capRimLine, boundaryBaseLine, topCurveLine;
let slicePlaneMesh, sliceRegionMesh, sliceOutlineLine, creamRimMesh;
let hiCap, hiWall, hiBase, hiCurve;

function rebuildSliceOnly() {
  if (sliceRegionMesh) {
    dynamicGroup.remove(sliceRegionMesh);
    disposeObject(sliceRegionMesh);
    sliceRegionMesh = null;
  }
  if (sliceOutlineLine) {
    dynamicGroup.remove(sliceOutlineLine);
    disposeObject(sliceOutlineLine);
    sliceOutlineLine = null;
  }
  if (slicePlaneMesh) slicePlaneMesh.position.y = currentH;

  const domain = [-2.18, 2.18];
  sliceRegionMesh = buildFlatRegion({
    h: currentH,
    domain,
    n: 92,
    predicate: (x, y) => safeEval(boundFn, x, y) <= 0 && safeEval(capFn, x, y) >= currentH,
    color: 0xfff2a6,
    opacity: 0.60
  });
  sliceRegionMesh.renderOrder = 7;
  dynamicGroup.add(sliceRegionMesh);

  const f = (x, y) => Math.max(safeEval(boundFn, x, y), currentH - safeEval(capFn, x, y));
  const segs = marchingSegments(f, domain, 116, 0);
  sliceOutlineLine = addSegments(linePointsFromSegs(segs, () => currentH + 0.025), new THREE.LineBasicMaterial({ color: 0x8d6a00, transparent: true, opacity: 0.95 }), dynamicGroup);
  sliceOutlineLine.renderOrder = 8;
  updateVisibility();
}

function updateVisibility() {
  const view = document.getElementById("regionSolidView").value;
  const hi = document.getElementById("highlightPart").value;
  const baseOnly = view === "Base region";

  if (fullCapMesh) fullCapMesh.visible = !baseOnly;
  if (topPatchMesh) topPatchMesh.visible = !baseOnly;
  if (wallMesh) wallMesh.visible = !baseOnly;
  if (creamRimMesh) creamRimMesh.visible = !baseOnly;
  if (capRimLine) capRimLine.visible = !baseOnly;
  if (topCurveLine) topCurveLine.visible = !baseOnly;
  if (slicePlaneMesh) slicePlaneMesh.visible = !baseOnly && showSlice;
  if (sliceRegionMesh) sliceRegionMesh.visible = !baseOnly && showSlice;
  if (sliceOutlineLine) sliceOutlineLine.visible = !baseOnly && showSlice;
  if (boundaryBaseLine) boundaryBaseLine.visible = true;
  if (baseMesh) baseMesh.visible = true;

  if (hiCap) hiCap.visible = highlightActive && !baseOnly && hi === "Paraboloid cap";
  if (hiWall) hiWall.visible = highlightActive && !baseOnly && hi === "Cylinder wall";
  if (hiBase) hiBase.visible = highlightActive && hi === "Base disk";
  if (hiCurve) hiCurve.visible = highlightActive && !baseOnly && hi === "Intersection curves";
}

function registerCurrentMeshes() {
  if (fullCapMesh) registerInteractive(fullCapMesh, {
    title: "Paraboloid cap",
    tooltip: "z = 4 − x² − y²",
    body: "The upper bounding surface is the downward-opening paraboloid. The orange crown is high; the blue rim is near z = 0."
  });
  if (wallMesh) registerInteractive(wallMesh, {
    title: "Cylinder wall",
    tooltip: "(x−1)² + y² = 1",
    body: "This vertical cylinder is centered at x = 1, tangent to the origin, and clipped by the paraboloid along its upper edge."
  });
  if (baseMesh) registerInteractive(baseMesh, {
    title: "Base disk",
    tooltip: "Base region in the xy-plane",
    body: "The disk (x−1)² + y² ≤ 1 lies in the xy-plane. It is the footprint of the bounded solid."
  });
}

function rebuildDynamic() {
  clearGroup(dynamicGroup);
  const domain = [-2.18, 2.18];

  fullCapMesh = buildPolarCap({ radial: 46, angular: 176, opacity: 0.54 });
  fullCapMesh.renderOrder = 1;
  dynamicGroup.add(fullCapMesh);

  topPatchMesh = buildGridSurface({
    domain,
    n: 76,
    predicate: (x, y) => safeEval(boundFn, x, y) <= 0 && safeEval(capFn, x, y) >= 0,
    heightFn: (x, y) => Math.max(0, safeEval(capFn, x, y)),
    opacity: 0.60
  });
  topPatchMesh.renderOrder = 4;
  dynamicGroup.add(topPatchMesh);

  baseMesh = buildFlatRegion({
    h: 0,
    domain,
    n: 90,
    predicate: (x, y) => safeEval(boundFn, x, y) <= 0 && safeEval(capFn, x, y) >= -0.02,
    color: 0x78b5dd,
    opacity: 0.43
  });
  baseMesh.renderOrder = 2;
  dynamicGroup.add(baseMesh);

  const bSegs = marchingSegments(boundFn, domain, 116, 0);
  wallMesh = buildWallFromBoundary(bSegs);
  wallMesh.renderOrder = 5;
  dynamicGroup.add(wallMesh);

  creamRimMesh = buildCreamRimBand();
  creamRimMesh.renderOrder = 6;
  dynamicGroup.add(creamRimMesh);

  const capPts = [];
  for (let i = 0; i < 180; i++) {
    const t0 = 2 * Math.PI * i / 180;
    const t1 = 2 * Math.PI * (i + 1) / 180;
    capPts.push(mathToWorld(2 * Math.cos(t0), 2 * Math.sin(t0), 0.01), mathToWorld(2 * Math.cos(t1), 2 * Math.sin(t1), 0.01));
  }
  capRimLine = addSegments(capPts, new THREE.LineBasicMaterial({ color: 0x2d6f99, transparent: true, opacity: 0.78 }), dynamicGroup);
  boundaryBaseLine = addSegments(linePointsFromSegs(bSegs, () => 0.018), new THREE.LineBasicMaterial({ color: 0x1f6088, transparent: true, opacity: 0.92 }), dynamicGroup);
  topCurveLine = addSegments(linePointsFromSegs(bSegs, (x, y) => Math.max(0, safeEval(capFn, x, y) + 0.022)), new THREE.LineBasicMaterial({ color: 0x9b493d, transparent: true, opacity: 0.98 }), dynamicGroup);
  topCurveLine.renderOrder = 6;

  slicePlaneMesh = buildSlicePlane(currentH);
  slicePlaneMesh.renderOrder = 7;
  dynamicGroup.add(slicePlaneMesh);

  rebuildSliceOnly();

  hiCap = topPatchMesh.clone();
  hiCap.material = new THREE.MeshBasicMaterial({ color: 0xffd36b, transparent: true, opacity: 0.20, side: THREE.DoubleSide, depthWrite: false });
  hiCap.renderOrder = 9;
  dynamicGroup.add(hiCap);

  hiWall = wallMesh.clone();
  hiWall.material = new THREE.MeshBasicMaterial({ color: 0xf4e58b, transparent: true, opacity: 0.25, side: THREE.DoubleSide, depthWrite: false });
  hiWall.renderOrder = 9;
  dynamicGroup.add(hiWall);

  hiBase = baseMesh.clone();
  hiBase.material = new THREE.MeshBasicMaterial({ color: 0xffe27a, transparent: true, opacity: 0.42, side: THREE.DoubleSide, depthWrite: false });
  hiBase.renderOrder = 9;
  dynamicGroup.add(hiBase);

  hiCurve = addSegments(linePointsFromSegs(bSegs, (x, y) => Math.max(0, safeEval(capFn, x, y) + 0.045)), new THREE.LineBasicMaterial({ color: 0xff2a00, transparent: true, opacity: 1 }), dynamicGroup);
  hiCurve.renderOrder = 10;

  registerCurrentMeshes();
  updateVisibility();
}

rebuildDynamic();

