const demoSteps = [
  {
    title: "Start with the base region",
    narration: "The circular disk in the xy-plane is the region (x − 1)² + y² ≤ 1. It is tangent to the origin and extends to x = 2 along the positive x-axis.",
    state: { regionSolidView: "Base region", highlightPart: "Base disk", sliceHeight: 0, showSlice: false }
  },
  {
    title: "Lift the base to the cap",
    narration: "Switching to the capped solid shows every point of the disk extruded upward until it hits z = 4 − x² − y².",
    state: { regionSolidView: "Capped solid", highlightPart: "Paraboloid cap", sliceHeight: 1, showSlice: false }
  },
  {
    title: "Locate the cylinder wall",
    narration: "The vertical wall keeps the same circular footprint at every height, but its top edge is cut by the paraboloid rather than by a flat plane.",
    state: { regionSolidView: "Capped solid", highlightPart: "Cylinder wall", sliceHeight: 1, showSlice: false }
  },
  {
    title: "Find the intersection curve",
    narration: "The closed curve marks where the cylinder and paraboloid meet. Along this curve, both equations are true at once.",
    state: { regionSolidView: "Capped solid", highlightPart: "Intersection curves", sliceHeight: 1, showSlice: false }
  },
  {
    title: "Move a horizontal slice upward",
    narration: "At low height the slice nearly fills the cylinder disk. Higher up, the paraboloid level circle shrinks the allowed cross-section.",
    state: { regionSolidView: "Capped solid", highlightPart: "Paraboloid cap", sliceHeight: 3, showSlice: true }
  }
];

let sliceTween = null;
window.goToStep = function goToStep(i) {
  const step = demoSteps[i];
  if (!step) return;
  highlightActive = true;
  showSlice = !!step.state.showSlice;
  document.getElementById("regionSolidView").value = step.state.regionSolidView;
  document.getElementById("highlightPart").value = step.state.highlightPart;
  document.getElementById("stepNarration").innerHTML = "<b>" + step.title + ".</b> " + step.narration;
  const start = currentH;
  const end = step.state.sliceHeight;
  const t0 = performance.now();
  if (sliceTween) cancelAnimationFrame(sliceTween);
  function run(t) {
    const u = Math.min(1, (t - t0) / 650);
    const e = u * u * (3 - 2 * u);
    currentH = start + (end - start) * e;
    document.getElementById("sliceHeight").value = currentH;
    document.getElementById("sliceVal").textContent = currentH.toFixed(1);
    rebuildSliceOnly();
    if (u < 1) sliceTween = requestAnimationFrame(run);
    else sliceTween = null;
  }
  updateVisibility();
  sliceTween = requestAnimationFrame(run);
};

for (let i = 0; i < 5; i++) {
  document.getElementById("step" + i).addEventListener("click", () => window.goToStep(i));
}

updateVisibility();
